import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.BwzYn71E.js";const k=JSON.parse('{"title":"一些临时的想法","description":"","frontmatter":{"translationSource":{"title":"一些临时的想法","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=wLO7awzBtdEXp0dRFq54zN","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/some-temporary-ideas"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/some-temporary-ideas"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/some-temporary-ideas"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/some-temporary-ideas"}]]},"headers":[],"relativePath":"zh/some-temporary-ideas.md","filePath":"zh/page-wLO7awzBtdEXp0dRFq54zN.md"}'),d={name:"zh/some-temporary-ideas.md"};function r(s,e,p,c,l,n){return a(),i("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="一些临时的想法" aria-hidden="true"></span><h1 id="一些临时的想法" tabindex="-1">一些临时的想法 <a class="header-anchor" href="#一些临时的想法" aria-label="Permalink to &quot;一些临时的想法&quot;">​</a></h1><blockquote><p>源页面 ID：<code>wLO7awzBtdEXp0dRFq54zN</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=wLO7awzBtdEXp0dRFq54zN" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>假定任意元件在计算时只是输出，非分流器的元件在计算时如果遇到下游为汇流器的情况，应该激活汇流器的其他非汇流器上游，尝试通过汇流器的轮询计数决定哪一者成功输入。</p><p>协议箱在优先输出时，汇流器输出端是可以轮询输入的，考虑到复现优先输出的&quot;先连接上游者&quot;，如果是运算到汇流器上游元件后发生上述轮询，导致协议箱的输出（被视为非分流器）与汇流器其他输入轮询，而正常情况下协议箱会在整个物流系统后进行输出，在计算过程只会随着其下游元件的层级顺序计算添加到一个特殊数据结构（类似末端序的结构，但是其中汇流器是特殊的）中便于轮询，就可以达成这个现象，取货口与反应池出口则采用完全不同的逻辑，导致其必须要在整个物流系统后才输出，不会受到上述轮询的影响。</p><p>标准工厂在尝试无缝切换配方时会发生什么，考虑到同一配方连续进行与不同配方进行卡1tick与同一产物可以无缝继续反应和不同产物需要等之前的产物输出后才能输出的对称性，是否可以认为切换配方时产物输出没能输出就经过了开始配方，所以跳过了本应该在同一帧进行的开始下一个配方，在下一tick时才成功输出并开始了配方，由此思路，应该排序为(工厂输入-物流系统)-工厂输出-结束配方-开始配方，是一个合理的解，但是这样即使改动物流系统也不会导致这个卡顿被变化（工厂输出不会被延迟到或者提前到结束配方到开始配方之间），对于我们的串行混产有影响而无法完全解决（增加切换周期也只是缓解）。显然的，除了这个解还有很多其他解，但是我无法确定是否都造成一样的结果。基于新的实验现象，在反应结果满时，同时有外源输入和反应结果试图进入反应结果池槽位中时，输出一滴液体，反应会结束，这是因为过程输出后会在同一tick内进行结束配方，而输入要等到下一tick。这个解释有一个问题，那就是每个配方只有一种材料的多种配方切换时不会卡1tick，这是一个反例。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4d8752ebec3d70cb.q90-f8b22f1246ad9ef2.webp" alt="一些临时的想法"></p><p>0tick a输入 a反应，8tick b输入 A反应完成 b反应，9tick A输出，16tick a输入 b反应完成 a反应 ，好像又没有问题</p><p>现在发现反应池多产物配方的产物又会优先输出了，见鬼。</p><p>考虑另外一个解，汇流器计算时会在输出后轮询其上游尝试拉取，且分流器无法拉取，保证反应池和取货口最后输出。根据说明，汇流器的拉取必然要求可以拉取协议箱的内容物，是否可以构造一个情况，使得其拉取了尚未输入的输入，导致卡1tick？考虑该情况下<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a>的分流器汇流器同层时，解应当如何。假定汇流器先算时，毫无疑问，汇流器会输出并拉取上游传送带的输入而不是分流器的（因为分流器无法拉取），当分流器先算时，汇流器尚未输出，进而分流器不可能往里面分流，故总是不可能成功分流，与实际不符，故要与现实相符必然需要额外改动同层下的运算顺序逻辑。考虑到这可能引出一个完全不同的体系，留言于此，暂且放置一侧不理。</p><p>此外再有一解，当分流器-汇流器直连时，强制一个特定的优先级，此外汇流器采用拉取的方式。该方式自由度略高，例如指定优先级的方式和计算顺序上都可以说因为某些因素而改动，目前不知道如何确认正确性。</p><p>关于反应池，之前讨论的结果推测是，反应池中存在虚空缓存，产物会优先进入虚空缓存中，然后再进入实缓存，没有进入实缓存时视为反应无法完成，但是无法验证</p><p>PL 认为关于反应池产物优先输出还是优先反应的问题的答案与配方遍历顺序有关，目测</p></div>',1)])])}const f=t(d,[["render",r]]);export{k as __pageData,f as default};
